import numpy as np
from scipy.optimize import minimize

def objective(vars):
    x, y, z, w = vars
    return (x**4 + y**4 + z**4 + w**4) - 8 * (x**3 + y**3 + z**3 + w**3)

def constraint1(vars):
    x, y, z, w = vars
    return x + y + z + w - 12

def constraint2(vars):
    x, y, z, w = vars
    return x**2 + y**2 + z**2 + w**2 - 48

constraints = [
    {'type': 'eq', 'fun': constraint1},
    {'type': 'eq', 'fun': constraint2}
]

# Test the cases found:
# Case 1: 3+sqrt(3), 3-sqrt(3), 3+sqrt(3), 3-sqrt(3)
# Case 2a: 2, 2, 2, 6
# Case 2b: 4, 4, 4, 0

starts = [
    np.array([3+np.sqrt(3), 3-np.sqrt(3), 3+np.sqrt(3), 3-np.sqrt(3)]),
    np.array([2, 2, 2, 6]),
    np.array([4, 4, 4, 0]),
]

results = []
for i, start in enumerate(starts):
    res = minimize(objective, start, constraints=constraints, method='SLSQP', options={'ftol': 1e-12})
    results.append((i, res.fun, res.x))

for i, val, x in results:
    print(f"Case {i+1}: Value = {val}, Vars = {x}")

