solve_alt()

def solve_random():
    import numpy as np
    from scipy.optimize import minimize

    def objective(delta):
        return np.sum(delta**4) + 4 * np.sum(delta**3) - 756

    def constraint1(delta):
        return np.sum(delta)

    def constraint2(delta):
        return np.sum(delta**2) - 12

    cons = [{'type': 'eq', 'fun': constraint1},
            {'type': 'eq', 'fun': constraint2}]

    for _ in range(5):
        delta0 = np.random.randn(4)
        res = minimize(objective, delta0, constraints=cons, method='SLSQP')
        print(f"Result: {res.fun}")

solve_random()

